files.repo/Sources/PlantListView.swift:
import SwiftUI

struct Plant: Identifiable {
    let id = UUID()
    let name: String
    let daysUntilWatering: Int
}

struct PlantListView: View {
    let plants: [Plant]

    var body: some View {
        if plants.isEmpty {
            ContentUnavailableView("No plants yet", systemImage: "leaf", description: Text("Add a plant to start a watering schedule."))
        } else {
            List(plants) { plant in
                LabeledContent(plant.name, value: plant.daysUntilWatering == 0 ? "Water today" : "In \(plant.daysUntilWatering) days")
            }
        }
    }
}

#Preview("Plants") {
    PlantListView(plants: [
        Plant(name: "Monstera", daysUntilWatering: 0),
        Plant(name: "Basil", daysUntilWatering: 2),
        Plant(name: "Snake plant", daysUntilWatering: 12)
    ])
}

